_COMMON_SQL = "WITH RECURSIVE\nwanted(ord,nspname,relname,expected_kind) AS (\n VALUES (1,'mf'::text,'current_fund_facts'::text,'v'::text),\n        (2,'mf'::text,'fund_variants'::text,'r'::text)\n),\nroots AS (\n SELECT w.*,n.oid AS nspoid,c.oid AS reloid\n FROM wanted w\n LEFT JOIN pg_catalog.pg_namespace n ON n.nspname=w.nspname\n LEFT JOIN pg_catalog.pg_class c ON c.relnamespace=n.oid AND c.relname=w.relname\n),\nrelations(oid) AS (\n SELECT reloid FROM roots WHERE reloid IS NOT NULL\n UNION\n SELECT e.refobjid\n FROM relations r\n CROSS JOIN LATERAL (\n   SELECT d.refobjid\n   FROM pg_catalog.pg_rewrite w\n   JOIN pg_catalog.pg_depend d ON d.classid='pg_catalog.pg_rewrite'::pg_catalog.regclass AND d.objid=w.oid\n   WHERE w.ev_class=r.oid AND w.rulename='_RETURN'\n     AND d.refclassid='pg_catalog.pg_class'::pg_catalog.regclass\n   UNION\n   SELECT d.refobjid\n   FROM pg_catalog.pg_policy p\n   JOIN pg_catalog.pg_depend d ON d.classid='pg_catalog.pg_policy'::pg_catalog.regclass AND d.objid=p.oid\n   WHERE p.polrelid=r.oid AND d.refclassid='pg_catalog.pg_class'::pg_catalog.regclass\n ) e\n),\nedges AS (\n SELECT r.oid AS source_relation,'view_return'::text AS source_kind,\n        d.classid,d.objid,d.objsubid,d.refclassid,d.refobjid,d.refobjsubid,d.deptype\n FROM relations r JOIN pg_catalog.pg_rewrite w ON w.ev_class=r.oid AND w.rulename='_RETURN'\n JOIN pg_catalog.pg_depend d ON d.classid='pg_catalog.pg_rewrite'::pg_catalog.regclass AND d.objid=w.oid\n UNION ALL\n SELECT r.oid,'policy'::text,d.classid,d.objid,d.objsubid,d.refclassid,d.refobjid,d.refobjsubid,d.deptype\n FROM relations r JOIN pg_catalog.pg_policy p ON p.polrelid=r.oid\n JOIN pg_catalog.pg_depend d ON d.classid='pg_catalog.pg_policy'::pg_catalog.regclass AND d.objid=p.oid\n),\nrelation_access(relation_oid,principal_oid) AS (\n SELECT r.reloid,u.oid FROM roots r CROSS JOIN pg_catalog.pg_roles u\n WHERE r.reloid IS NOT NULL AND u.rolname='mfdata_verified_reader'\n UNION\n SELECT e.refobjid,\n CASE WHEN EXISTS (\n   SELECT 1 FROM pg_catalog.pg_options_to_table(c.reloptions) o\n   WHERE o.option_name='security_invoker' AND o.option_value='true'\n ) THEN u.oid ELSE c.relowner END\n FROM relation_access a\n JOIN pg_catalog.pg_class c ON c.oid=a.relation_oid AND c.relkind='v'\n JOIN edges e ON e.source_relation=c.oid AND e.source_kind='view_return'\n CROSS JOIN pg_catalog.pg_roles u\n WHERE u.rolname='mfdata_verified_reader'\n   AND e.refclassid='pg_catalog.pg_class'::pg_catalog.regclass\n   AND e.refobjid<>e.source_relation\n),\noperators AS (\n SELECT o.* FROM pg_catalog.pg_operator o\n WHERE o.oid IN (SELECT refobjid FROM edges WHERE refclassid='pg_catalog.pg_operator'::pg_catalog.regclass)\n),\nfunctions(oid) AS (\n SELECT refobjid FROM edges WHERE refclassid='pg_catalog.pg_proc'::pg_catalog.regclass\n UNION SELECT oprcode::oid FROM operators WHERE oprcode::oid<>0\n),\nreader AS (SELECT oid FROM pg_catalog.pg_roles WHERE rolname='mfdata_verified_reader'),\nfunction_contexts(function_oid,execute_principal,body_principal,security_definer) AS (\n SELECT p.oid,u.oid,CASE WHEN p.prosecdef THEN p.proowner ELSE u.oid END,p.prosecdef\n FROM functions f JOIN pg_catalog.pg_proc p ON p.oid=f.oid CROSS JOIN reader u\n),\npolicy_role_targets(oid) AS (\n SELECT DISTINCT x.roleoid FROM pg_catalog.pg_policy p JOIN relations r ON r.oid=p.polrelid\n CROSS JOIN LATERAL pg_catalog.unnest(p.polroles) x(roleoid) WHERE x.roleoid<>0\n),\nidentity_context_roles(oid) AS (\n SELECT oid FROM reader\n UNION SELECT c.relowner FROM pg_catalog.pg_class c JOIN relations r ON r.oid=c.oid\n UNION SELECT p.proowner FROM pg_catalog.pg_proc p JOIN functions f ON f.oid=p.oid\n UNION SELECT oid FROM policy_role_targets\n),\nmembership_seeds(oid) AS (\n SELECT oid FROM reader\n UNION SELECT principal_oid FROM relation_access\n UNION SELECT body_principal FROM function_contexts WHERE security_definer\n),\nancestors(oid) AS (\n SELECT oid FROM membership_seeds\n UNION SELECT m.roleid FROM ancestors a JOIN pg_catalog.pg_auth_members m ON m.member=a.oid\n),\nreader_descendants(oid) AS (\n SELECT oid FROM reader\n UNION SELECT m.member FROM reader_descendants d JOIN pg_catalog.pg_auth_members m ON m.roleid=d.oid\n),\nrelevant_roles(oid) AS (SELECT oid FROM ancestors UNION SELECT oid FROM reader_descendants UNION SELECT oid FROM identity_context_roles),\nmembership_edges AS (\n SELECT m.* FROM pg_catalog.pg_auth_members m\n WHERE m.member IN (SELECT oid FROM ancestors) OR m.roleid IN (SELECT oid FROM reader_descendants)\n),\nroot_acl_objects(object_kind,object_oid,sub_id,owner_oid,acl_kind,raw_acl) AS (\n SELECT 'relation'::text,c.oid,0,c.relowner,'r'::pg_catalog.\"char\",c.relacl\n FROM roots r JOIN pg_catalog.pg_class c ON c.oid=r.reloid\n UNION ALL\n SELECT 'schema'::text,n.oid,0,n.nspowner,'n'::pg_catalog.\"char\",n.nspacl\n FROM pg_catalog.pg_namespace n WHERE n.nspname='mf'\n UNION ALL\n SELECT 'column'::text,a.attrelid,a.attnum::integer,c.relowner,'c'::pg_catalog.\"char\",a.attacl\n FROM roots r JOIN pg_catalog.pg_class c ON c.oid=r.reloid\n JOIN pg_catalog.pg_attribute a ON a.attrelid=c.oid AND a.attnum>0\n),\nroot_acl_rows AS (\n SELECT o.object_kind,o.object_oid,o.sub_id,x.grantor,x.grantee,x.privilege_type,x.is_grantable\n FROM root_acl_objects o\n CROSS JOIN LATERAL pg_catalog.aclexplode(COALESCE(o.raw_acl,pg_catalog.acldefault(o.acl_kind,o.owner_oid))) x\n),\nidentity_role_oids(oid) AS (\n SELECT oid FROM relevant_roles\n UNION SELECT grantor FROM membership_edges\n UNION SELECT grantor FROM root_acl_rows\n UNION SELECT grantee FROM root_acl_rows WHERE grantee<>0\n)"
